#!/usr/bin/env node
// Benchmark harness for docs/design/streaming-rpc-links.md.
//
// Compares two ways to shape a link chain of depth `DEPTH`, run
// `ITERATIONS` times:
//
//   1. "async"     — today's `RpcLink` contract: `(req, next) =>
//                     Promise<Response>`, exactly as generated by
//                     rpc-runtime.ts.j2.
//   2. "generator" — the unification this doc evaluates and rejects:
//                     `(req, next) => AsyncGenerator<Response>`, a
//                     unary call becomes a one-item stream.
//
// Each is measured standalone (chain overhead in isolation) and again
// with a simulated network hop per call (chain overhead as a fraction
// of a realistic call — an empty-chain microbenchmark alone
// exaggerates generator overhead into irrelevance, since real network
// latency dwarfs it; see the design doc's Risks section).
//
// Run: node docs/design/streaming-rpc-links/bench.mjs
// No dependencies — plain Node, matches this repo's `engines.node
// >=18` floor for the @cratestack/* packages this chain type lives in.

const DEPTH = 4; // mirrors the ticket's "realistic depth (3-5 links)"
const ITERATIONS = 200_000;
const SIMULATED_NETWORK_MS = 5; // a fast same-region HTTP round trip

function composeAsync(links, terminal) {
  return links.reduceRight((next, link) => (req) => link(req, next), terminal);
}

function makeAsyncChain(depth, terminal) {
  const links = Array.from({ length: depth }, () => async (req, next) => next(req));
  return composeAsync(links, terminal);
}

function composeGen(links, terminal) {
  return links.reduceRight((next, link) => (req) => link(req, next), terminal);
}

function makeGenChain(depth, terminal) {
  const links = Array.from({ length: depth }, () => async function* (req, next) {
    yield* next(req);
  });
  return composeGen(links, terminal);
}

async function drain(asyncIterable) {
  let last;
  for await (const value of asyncIterable) {
    last = value;
  }
  return last;
}

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function timeIt(label, iterations, run) {
  // Warm up the JIT before measuring, same reasoning as any
  // microbenchmark: the first few thousand calls are dominated by
  // deopt/inline-cache churn, not steady-state cost.
  for (let i = 0; i < 2_000; i++) {
    await run(i);
  }
  const start = process.hrtime.bigint();
  for (let i = 0; i < iterations; i++) {
    await run(i);
  }
  const totalMs = Number(process.hrtime.bigint() - start) / 1e6;
  const perCallUs = (totalMs * 1000) / iterations;
  console.log(`${label.padEnd(38)} total ${totalMs.toFixed(1)}ms  per-call ${perCallUs.toFixed(3)}us`);
  return perCallUs;
}

async function main() {
  console.log(`depth=${DEPTH} iterations=${ITERATIONS} node=${process.version}\n`);

  console.log("-- chain overhead in isolation (no network) --");
  const asyncTerminal = async (req) => req;
  const asyncChain = makeAsyncChain(DEPTH, asyncTerminal);
  const genTerminal = async function* (req) {
    yield req;
  };
  const genChain = makeGenChain(DEPTH, genTerminal);

  const asyncUs = await timeIt("async-function chain", ITERATIONS, (i) => asyncChain(i));
  const genUs = await timeIt("async-generator chain", ITERATIONS, (i) => drain(genChain(i)));
  console.log(`\ngenerator overhead vs async-function: ${(((genUs - asyncUs) / asyncUs) * 100).toFixed(1)}%\n`);

  console.log(`-- chain overhead as a fraction of a realistic call (+${SIMULATED_NETWORK_MS}ms network) --`);
  const networkIterations = 2_000; // fewer — each call now costs real wall-clock ms
  const asyncTerminalNet = async (req) => {
    await delay(SIMULATED_NETWORK_MS);
    return req;
  };
  const asyncChainNet = makeAsyncChain(DEPTH, asyncTerminalNet);
  const genTerminalNet = async function* (req) {
    await delay(SIMULATED_NETWORK_MS);
    yield req;
  };
  const genChainNet = makeGenChain(DEPTH, genTerminalNet);

  const asyncNetUs = await timeIt("async-function chain + network", networkIterations, (i) => asyncChainNet(i));
  const genNetUs = await timeIt("async-generator chain + network", networkIterations, (i) => drain(genChainNet(i)));
  console.log(
    `\ngenerator overhead vs async-function, with network: ${(((genNetUs - asyncNetUs) / asyncNetUs) * 100).toFixed(3)}%`,
  );
}

main();
